// New source-only lifecycle regressions appended after the seventeen frozen callbacks.
// Original MoveFX + original BattlePresentation create/ACK; UNIT keys/actor marks
// and a deferred audio.finish stand-in are explicit. No Game/GEN5/R6 raster.
async function completedAudioTail({corrupt}={}){
 const h=await boot(),flow=await wholeMoveFlow(h,{holdFinish:true}),work=flow.play(),outcome={settled:0,error:null};
 work.then(()=>outcome.settled++,error=>{outcome.settled++;outcome.error=error;});
 for(let i=0;i<200&&!h.c.MoveFX.active&&!outcome.error;i++)await new Promise(r=>setTimeout(r,1));if(outcome.error)throw outcome.error;
 const x=h.c.MoveFX.active;assert(x?.presentationClock);let last;
 for(let i=0;i<3;i++){last=flow.originalArenaStep(corrupt);if(last.ack.complete)break;}
 assert(last.ack.complete&&last.ack.frame===126);assert.equal(x.presentationCompleting,true);assert.equal(x.presentationClock.snapshot().complete,true);
 await Promise.resolve();assert.equal(flow.finishEntered,true);return{h,flow,work,outcome,x,last};
}
function noPins(h){const r=h.S.tynamo33NativeFoe064.read();for(const k of['pendingMetadata','pinnedMetadata','pendingBankPins','pendingMetadataPins','boundBankPins','boundMetadataPins','ownedJobs'])assert.equal(r[k],0,k);assert.equal(h.pinBalance,0);return r;}
test('accepted original completeACK releases pins while repeated before safely holds original126 until deferred audio finish',async()=>{
 const t=await completedAudioTail(),{h,flow,work,outcome,x}=t,before=noPins(h),loads=h.loads;
 assert.equal(before.awaitingAcknowledgedAudioTail,true);assert.equal(outcome.settled,0);
 for(let i=0;i<5;i++){assert.notEqual(h.S.beforeArenaFrame(h.layout.p1.w,h.layout.p1.h),false);assert.equal(h.c.MoveFX.beginArenaFrame(),null);assert.equal(h.c.MoveFX.nativeTynamoFrame064(null),true);assert.equal(h.c.MoveFX.active,x);assert.equal(outcome.settled,0);noPins(h);}
 assert.equal(h.loads,loads);assert.equal(h.S.tynamo33NativeFoe064.read().coldSolves,before.coldSolves);assert.equal(flow.counts.clock,1);assert.equal(flow.counts.timerFallback,0);assert.equal(flow.counts.beginFallback,0);
 flow.resolveFinish();await bounded(work,250,'DEFERRED_FINISH_DID_NOT_SETTLE');assert.equal(outcome.settled,1);assert.equal(outcome.error,null);assert.equal(h.c.MoveFX.active,null);assert.equal(noPins(h).awaitingAcknowledgedAudioTail,false);assert.equal(h.renderAttempts,0);
});
